/**  Progress events for sync operations */
export type SyncEvent = 
/**  Sent at the beginning with issue navigation configuration if found */
{ type: "issueNavigationConfig"; data: {
	config: IssueNavigationConfig | null,
} } | 
/**  Sent immediately after grouping commits */
{ type: "branchesGrouped"; data: {
	branches: GroupedBranchInfo[],
	/**  Repository's baseline branch (e.g., "origin/master", "master") */
	baselineBranch: string,
	/**  Stacked branches are on (`branchdeck.stacks`): prefixes are read as `(parent/leaf)` */
	stacks?: boolean,
	/**  Issue key -> branch name: the issue groups (`refs/branch-deck/issue-groups`) the commits were grouped with */
	issueGroups?: { [key in string]: string },
	/**
	 *  Child -> parent: the stack parents (`refs/branch-deck/stack-parents`) the branches were placed with; empty with
	 *  stacked branches off
	 */
	stackParents?: { [key in string]: string },
} } | 
/**  Sent for commits that don't match any prefix pattern */
{ type: "unassignedCommits"; data: {
	commits: Commit[],
} } | 
/**  Sent when a commit is successfully cherry-picked */
{ type: "commitSynced"; data: {
	branchName: string,
	commitHash: string,
	newHash: string,
	status: CommitSyncStatus,
} } | 
/**  Sent when a commit fails to cherry-pick */
{ type: "commitError"; data: {
	branchName: string,
	commitHash: string,
	error: BranchError,
} } | 
/**  Sent to mark commits as blocked due to earlier error */
{ type: "commitsBlocked"; data: {
	branchName: string,
	blockedCommitHashes: string[],
} } | 
/**  Sent when a branch status changes (including during processing and completion) */
{ type: "branchStatusUpdate"; data: {
	branchName: string,
	status: BranchSyncStatus,
	error: BranchError | null,
} } | 
/**  Unified per-branch detection event for any status (Integrated, Orphaned, `NotIntegrated`, Partial) */
{ type: "branchIntegrationDetected"; data: {
	info: BranchIntegrationInfo,
} } | 
/**  Sent immediately when archived branches are found (before expensive detection) */
{ type: "archivedBranchesFound"; data: {
	branchNames: string[],
	/**  The branches this sync archived, a subset of `branch_names` */
	newlyArchived: string[],
} } | 
/**  Sent when remote branch status is checked */
{ type: "remoteStatusUpdate"; data: RemoteStatusUpdate } | 
/**
 *  Sent once after `BranchesGrouped`: whether the checked out branch can be updated onto the last fetched baseline
 *  (checked without the network). Both fields `None` for a local baseline, which has nothing to update from.
 */
{ type: "baselineStatus"; data: {
	baselineBranch: string,
	update: UpdateCheck | null,
	/**  Why the check failed, e.g. a rebase in progress; the sync itself does not fail */
	checkError: string | null,
	/**  Local commits that the fetched baseline already has: the update drops them */
	landing: LandedBranch[],
	/**  Commits that landed with an update (by Branch Deck or elsewhere) and that the user has not dismissed yet */
	landed: LandedBranch[],
} };

/**  Where the GitHub token came from, in the order they are tried (`github::token`) */
export type TokenSource = 
/**  `GH_TOKEN`, else `GITHUB_TOKEN` */
"environment" | 
/**  `gh auth token` */
"gh" | 
/**  The app's own sign-in (OAuth device flow) */
"branchDeck" | 
/**  The credential git stores for github.com (`git credential fill`) */
"gitCredential";

/**  How far a fetch or a push is, for the button that runs it */
export type TransferProgress = {
	/**  The whole transfer, 0 to 100, never decreasing */
	percent: number,
	/**  Received (fetch) or sent (push) so far, as git prints it, e.g. "5.79 MiB" */
	transferred: string | null,
	/**  The transfer rate, as git prints it, e.g. "32.57 MiB/s" */
	speed: string | null,
	/**  The last progress line of git, without the `remote: ` prefix, e.g. "Receiving objects:  45% (136/302)" */
	line: string,
};

export type UnapplyBranchParams = {
	repositoryPath: string,
	branchName: string,
	branchPrefix: string,
	originalCommitIds: string[],
};

export type UnapplyBranchResult = {
	unappliedBranchName: string,
	commitsRemoved: string[],
};

export type UncommittedChangesResult = {
	hasChanges: boolean,
	files: UncommittedFileChange[],
};

export type UncommittedFileChange = {
	filePath: string,
	status: string,
	staged: boolean,
	unstaged: boolean,
};

export type UndoRegroupParams = {
	repositoryPath: string,
	/**  What the operation reported in `MoveCommitsResult.undo_token` */
	token: string,
};

/**  The result of checking the branch against its upstream */
export type UpdateCheck = {
	/**  The checked out branch, short name */
	branch: string,
	/**  The upstream as the user knows it, e.g. `origin/master` */
	upstream: string,
	head: string,
	upstreamHead: string,
	/**  The merge base of HEAD and the upstream */
	base: string,
	state: UpdateState,
	/**  When the upstream was last fetched (Unix seconds), if known */
	fetchedAt: number | null,
};

/**  A commit of a conflicting update: a local one that would be replayed, or an upstream one */
export type UpdateCommit = {
	id: string,
	subject: string,
	author: string,
	/**  Author time, Unix seconds */
	time: number,
	/**  Who wrote the commit object: the author, or whoever rebased or landed it (a Safe Push robot) */
	committer: string,
	/**  Committer time, Unix seconds: for an upstream commit, about when it reached the upstream */
	committerTime: number,
	/**  The likely conflicting files that the commit changes; empty for most commits */
	files: string[],
};

export type UpdateInfo = {
	current_version: string,
	/**  Empty when no update is available */
	available_version: string,
	is_update_available: boolean,
	status: UpdateStatus,
};

/**  How the branch reaches the upstream */
export type UpdateKind = 
/**  No local commits: the branch moves to the upstream */
"fastForward" | 
/**  The local commits are replayed onto the upstream */
"rebase";

/**  The step an update is at */
export type UpdatePhase = "fetching" | "checking" | "updating";

/**  What an update reports while it runs */
export type UpdateProgress = {
	phase: UpdatePhase,
	/**  How far the fetch is; `None` until git reports a stage, and in the other phases */
	fetch: TransferProgress | null,
};

export type UpdateProjectParams = {
	repositoryPath: string,
};

export type UpdateProjectResult = {
	/**  The check against the fetched upstream; on a conflict or a block nothing was changed */
	check: UpdateCheck,
	/**  What the update changed; `None` when up to date, conflicting or blocked */
	applied: AppliedUpdate | null,
	/**  The local commits this update dropped because the upstream has them, by branch */
	landed: LandedBranch[],
};

/**  Whether the branch can be updated, relative to the last fetch of the upstream */
export type UpdateState = 
/**  The upstream has nothing the branch lacks */
{ status: "upToDate" } | 
/**  The update applies without conflicts and without touching local changes */
{ status: "clean"; kind: UpdateKind } | 
/**  Replaying the local commits onto the upstream conflicts; nothing was changed */
{ status: "conflict"; 
/**  The files that likely conflict */
files: string[]; 
/**  The local commits, oldest first */
commits: UpdateCommit[]; 
/**
 *  The upstream commits that changed the likely conflicting files, oldest first, at most the newest
 *  `MAX_UPSTREAM_COMMITS`
 */
upstreamCommits: UpdateCommit[] } | 
/**  Uncommitted or staged changes, or untracked files, sit on paths the update would write; nothing was changed */
{ status: "blocked"; paths: string[] };

export type UpdateStatus = "Idle" | "Checking" | "Downloading" | "Downloaded" | "Installing" | { Error: string };

/**  A commit of the baseline that carries the user's work */
export type UpstreamCommit = {
	id: string,
	author: string,
	committer: string,
	/**  Commit time, Unix seconds */
	time: number,
};

export type ValidateRepositoryPathParams = {
	path: string,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

